// 银行系统教学内容（构建时固化）。
//
// 口径：业务与技术按行业通行知识写；厂商与案例只用公开资料口径，
// 具体数字凡引用均在条目内标注来源口径（年报 / 厂商口径 / 公开报道），
// 核不到的写「未公开」。中美对照只讲路线差异，不做高下评判。
// 行业通用规则（如贷款五级分类的逾期天数参考、结息日）按通行标准写明。

export interface PanoramaModule {
  id: string;
  name: string;
  en: string;
  role: string;
  boundary: string;
  interact: string;
  example: string;
  misconception: string;
}

export interface PanoramaLayer {
  id: string;
  name: string;
  en: string;
  note: string;
  modules: PanoramaModule[];
}

