        boundary: "数据平台（数仓）管「把数据汇起来、算出来」，数据治理管「数据对不对、口径一不一致、出了问题谁负责」。治理不生产业务数据：它给源头系统立录入标准、给下游用数划口径红线。源头不改，治理只能在下游打补丁——补丁层数越多，同一个指标在不同报表里越对不上，这是数据治理要根治的病，而不是它存在的理由。",
        interact: "向上约束全部源头系统的数据标准与录入质量，质量检核问题以工单回写源头系统整改；向下供数给监管报送、风险计量、管理会计与经营分析；主数据变更广播到全部订阅系统；监管数据集市与报送系统对接，报送口径变更先在集市层调整、再传导到各报表。",
        example: "「不良贷款余额」曾在信贷系统、风险报表、1104 报表里出现三个不同的数：治理工作先由业务部门裁定统一定义（五级分类口径 + 月末时点口径），再在监管数据集市固化一套取数逻辑并登记血缘，三张报表从此同源同数。监管现场检查调数时，银行能沿血缘一路追到源头系统的表与字段、说清每个数字的来历——说不清来历的数字，在监管眼里等于没有数字。",
