        example: "国内进口商从德国进口设备，开出一张 90 天远期信用证：开证行冻结保证金并开证（MT700 报文经 SWIFT 发出），德国出口商发货后把提单、发票、装箱单全套单据交议付行寄到开证行，开证行在 5 个银行工作日内审单——单证相符即承兑，生成一笔 90 天后到期的银行承兑债务。进口商凭信托收据先借单提货销售，90 天到期付款赎单；出口商若急需现金，可把已承兑的信用证做福费廷无追索卖断、提前回款。一张信用证同时解决了互信、账期与融资三件事——这就是它发明一百多年仍未被取代的原因。",
