      body: "王某获批经营贷 100 万元、期限 12 个月、年利率 4.35%（LPR 加点示例）、等额本息、受托支付给设备供应商。① 放款日：信贷系统核销抵押登记等条件后发指令，核心记账——借：贷款——王某 1,000,000 元；贷：供应商在他行账户的清算往账 1,000,000 元（经支付系统划出）。王某的存款账户全程没见过这笔钱，这是受托支付的账务形态。② 每日计提：1,000,000 × 4.35% ÷ 360 ≈ 120.83 元/日，借：应收利息；贷：利息收入。③ 每月还款约 85,380 元（等额本息测算值）：第 1 期含利息约 3,625 元、本金约 81,755 元，扣款分录——借：王某存款账户 85,380 元；贷：应收利息 3,625 元、贷：贷款本金 81,755 元。此后每月利息随剩余本金下降、本金占比上升。④ 若第 6 期扣款日账户只有 20,000 元：按合同顺序先冲利息与费用，不足部分本金转逾期，逾期本金按 4.35% × 1.5 = 6.525% 计罚息，借据状态变更并回传信贷系统启动催收与分类评估。⑤ 第 12 期结清：本金余额归零，授信额度 100 万元全额释放，抵押注销，全周期利息合计约 23,760 元。",
