          us: "以《银行保密法》（BSA）为核心，财政部 FinCEN 负责，银行报送可疑活动报告（SAR）与大额现金交易报告（CTR，1 万美元现金线为公开制度）——制度骨架相似，执法强度与罚金规模以美国为最著称。",
