export const TERMS: Term[] = [
  { id: "t-daycut", term: "日切", en: "Day Cut / EOD", plain: "银行按下「今天结束」的按钮，把营业日期拨到明天，中间集中算清全天的账。", pro: "核心系统切换营业日的时点与过程，日切后启动日终批处理链，期间发生的交易归入新营业日。", example: "场景：你深夜 23:50 转账，银行日切点在 23:30，这笔交易记入下一个营业日——跨日利息与限额都按新营业日算。易混：日切 ≠ 系统关机，渠道照常营业，只是账务日期换了。" },
  { id: "t-zhazhang", term: "轧账", en: "Balancing", plain: "把一天的账全部对一遍：借方总数必须等于贷方总数，分毫不差才算过关。", pro: "日终对全部账簿进行平衡校验，包括借贷平衡、总分相符与账账相符；不平则挂账处理并追查差错。", example: "场景：柜员日终轧账发现现金短款 200 元，要当场查流水与监控，查不清先挂账次日追清。易混：轧账是「自己跟自己对（借贷平不平）」，对账是「自己跟别人对（与客户、与他行）」，轧账在内、对账在外。" },
  { id: "t-clearing", term: "清算", en: "Clearing", plain: "算账：把银行之间你欠我、我欠你的一堆交易轧出一个净数。", pro: "对金融机构间债权债务进行计算与轧差、形成待交割净额的过程，本身不发生资金转移。", example: "场景：银联当晚算出工行应收 30 亿、应付 28 亿，净收 2 亿——这一步是清算，钱还没动。易混：清算 vs 结算——清算是算出净额，结算是把净额的钱真正划走；「已清算」不等于「已到账」。" },
  { id: "t-settlement", term: "结算", en: "Settlement", plain: "交割：按算好的账真正把钱划过去，债务两清。", pro: "依据清算结果在央行清算账户等载体上完成资金划拨，清算债权债务就此消灭，具有最终性。", example: "场景：轧差后的净额在央行清算账户上完成划拨，银行间债务清零，这一步才叫结算完成。易混：日常说的「支付结算」是广义业务统称，技术语境里的「结算」专指资金交割这一步。" },
  { id: "t-toucu", term: "头寸", en: "Position / Funds Position", plain: "银行手头此刻真正能动用的钱有多少，管钱的人全天盯着它。", pro: "金融机构在特定时点可支配资金的余额状况；头寸管理负责预报、调度与调拨，防止清算账户透支或排队。", example: "场景：下午 4 点头寸岗发现清算账户余额不足以覆盖一笔即将发出的大额付款，紧急从同业市场拆入资金补头寸。易混：头寸 ≠ 存款余额，头寸是银行自己的可用资金，存款是银行欠客户的钱。" },
  { id: "t-reserve", term: "法定存款准备金", en: "Required Reserves", plain: "银行每收一笔存款，要按比例上交央行「压着」不能动的一部分。", pro: "商业银行按央行规定的比例将吸收存款的一部分缴存中央银行，是货币政策与流动性管理工具；缴存部分构成超额准备金之外的受限资金。", example: "场景：某行吸收存款 1,000 亿元、准备金率约 9% 量级，约 90 亿元要缴存央行不能放贷。易混：法定准备金（强制缴存）vs 超额准备金（自愿多存、用于清算），两者在央行账户上是两个科目。" },
  { id: "t-interbank", term: "同业", en: "Interbank", plain: "银行和银行（及非银金融机构）之间打交道的业务统称：互相存款、拆借、买债都算。", pro: "金融机构之间的资金融通与业务往来，包括同业存放、同业拆借、同业存单等，价格由市场利率（如 SHIBOR）决定。", example: "场景：A 银行今天钱多，把 10 亿元隔夜拆给缺钱的 B 银行，利率按 SHIBOR 隔夜价——这是同业拆借。易混：「同业」是对手方维度（跟金融机构做），与之相对的是「对公/对私」（跟企业/个人做）。" },
  { id: "t-online", term: "联机处理", en: "Online Transaction Processing", plain: "来一笔办一笔、立刻出结果，像柜台当面办事。", pro: "交易请求实时逐笔处理并立即返回结果（OLTP），要求低时延、高并发与强一致，典型如转账、授权。", example: "场景：刷卡授权 1 秒内返回批准——联机处理。易混：联机看「单笔时延」，批量看「整体吞吐」，同一笔代发工资业务里两者同时存在（联机提交、批量入账）。" },
  { id: "t-batch", term: "批量处理", en: "Batch Processing", plain: "把活攒成一堆一起干，像夜里集中发工资。", pro: "将大量同类交易打包后按计划集中处理，追求吞吐与单位成本，由调度系统按作业依赖编排，常运行于日终窗口。", example: "场景：代扣水电费每月 15 号凌晨整包执行，几万笔一起扣。易混：批量 ≠ 慢，批量的单笔成本远低于联机，慢的是「等到攒批」的那段时间。" },
  { id: "t-reversal", term: "冲正", en: "Reversal", plain: "发现一笔账记错了或结果不明，用一笔反方向的账把它抵消，回到没发生过的状态。", pro: "以反向分录冲销原交易账务的处理机制，是超时、结果不明等异常场景下保证账务终态明确的标准手段。", example: "场景：ATM 扣了款却没吐钞，系统自动冲正，钱回到账户。易混：冲正 vs 退汇——冲正是本行内部撤销自己记错的账，退汇是收款行无法入账把钱原路退回，发起方与场景都不同。" },
  { id: "t-suspense", term: "挂账", en: "Suspense Account", plain: "一时查不清归属的钱先临时停在一个过渡账户里，查清了再转走，不能不明不白放着。", pro: "对暂收、暂付及差错款项设置的过渡性科目管理，要求逐笔登记、限期清理，严禁长期挂账掩盖差错。", example: "场景：对账发现一笔 3 万元来账无匹配流水，先挂入待处理科目，次日查明是某笔退汇后补记入账。易混：挂账是「临时停车位」不是「销账」，挂账不清零是运营事故，拿挂账藏差错是违规。" },
  { id: "t-gl-check", term: "总分核对", en: "GL-Detail Reconciliation", plain: "总账上的总数，必须和每个业务模块的明细加起来一模一样，每天都要对。", pro: "日终将总账科目余额与各业务系统明细账汇总数逐项比对，是账务完整性的核心控制，不符即触发差错处理。", example: "场景：总账贷款科目余额比信贷模块明细之和少 0.01 元，当晚必须查出是哪笔分录漏传。易混：总分核对是行内纵向对账（总账 vs 明细），与和央行、银联的横向对账（账账核对）是两个方向。" },
  { id: "t-double-entry", term: "复式记账 / 借贷记账法", en: "Double-entry Bookkeeping", plain: "每一笔账都同时记两边：一边记钱从哪来，一边记钱到哪去，两边永远相等。", pro: "以「有借必有贷、借贷必相等」为规则的记账方法，借贷在此是记账符号而非字面借钱还钱，是全部会计核算的基础。", example: "场景：客户存入现金 1 万元——借：现金（银行资产增），贷：客户存款（银行负债增），两边同增 1 万。易混：这里的「借」不等于借钱，「贷」不等于放贷，方向含义随科目性质而定，先忘掉字面意思。" },
  { id: "t-cif", term: "CIF（客户信息文件）", en: "Customer Information File", plain: "银行给每个客户建的唯一档案：你是谁、你名下所有账户和卡都挂在这一页上。", pro: "核心系统中集中维护的客户主数据，以客户号唯一标识自然人或法人，并关联其全部账户与合约关系。", example: "场景：你在同一银行有 3 个账户、2 张卡、1 笔贷款，CIF 用一个客户号把它们串成「同一个你」。易混：CIF（法定主数据，核心内）vs 客户中心（经营视图，中台），前者求准、后者求全。" },
  { id: "t-classification", term: "贷款五级分类", en: "Five-category Loan Classification", plain: "按「还能不能收回来」给贷款分五档：正常、关注、次级、可疑、损失，后三档就是不良贷款。", pro: "以借款人还款能力与意愿为核心、结合逾期与担保情况的信贷资产质量分类制度，是不良率统计与拨备计提的基础。", example: "场景：一笔贷款逾期 100 天且企业现金流恶化，划入次级类（不良）；另一笔未逾期但企业已停产，也可能直接划入次级甚至可疑。易混：逾期天数是参考线不是自动标尺，分类看的是还款能力；「不良」= 次级 + 可疑 + 损失，不含关注。" },
  { id: "t-kyc", term: "KYC（了解你的客户）", en: "Know Your Customer", plain: "开户前银行必须搞清楚你是谁、钱从哪来、打算怎么用，搞不清就不给办。", pro: "金融机构在建立业务关系时对客户身份、受益所有人、职业与资金用途进行识别与核实的尽职调查要求。", example: "场景：对公开户要穿透股权找到最终受益人（持股 25% 为通行识别标准），找不到自然人控制者就开不了户。易混：KYC 是开户与存续期的身份/背景核查，反洗钱是交易监测体系，KYC 是反洗钱的地基但不是全部。" },
  { id: "t-aml", term: "反洗钱", en: "Anti-Money Laundering (AML)", plain: "盯着钱的来路去向，防止犯罪所得通过银行交易「洗白」。", pro: "金融机构依法履行客户尽职调查、大额与可疑交易报告、名单筛查与记录保存等义务的制度与系统体系。", example: "场景：账户 5 天内收到 27 笔贴着 5 万元线下方的转账又集中转出境外，触发可疑监测。易混：反洗钱管「钱干不干净」，反欺诈管「交易是不是本人」——一个防犯罪资金、一个防账户被盗，系统与团队都分开。" },
  { id: "t-netting", term: "轧差", en: "Netting", plain: "一堆互相欠的钱先两两抵消，最后只付差额——一万笔交易轧成一个数。", pro: "将多笔双边或多边债权债务相互抵销、仅对净额进行结算的安排，大幅降低结算资金占用与流动性风险。", example: "场景：A 行今日应收 B 行 80 亿、应付 78 亿，轧差后 B 行只需付 A 行 2 亿。易混：轧差是清算环节的计算方法，结算是轧差之后的资金动作；轧差不改变每笔交易的债权关系，只改变资金搬运量。" },
  { id: "t-class2", term: "二类户", en: "Class II Account", plain: "功能受限的银行账户：能理财能消费，但每天进出有额度上限，开户不用跑网点。", pro: "经电子渠道开立、未做柜面全量核验的个人银行结算账户，设有日累计与年累计交易限额，与一类户形成分级账户体系。", example: "场景：你在手机银行直接开的电子账户是二类户，日累计限额 1 万元（通行口径），大额资金要经绑定的一类户进出。易混：一类/二类/三类是同一银行内的核验强度分级，不是三家银行、也不是账户「等级贵贱」。" },
  { id: "t-accrual", term: "计息与结息", en: "Interest Accrual & Settlement", plain: "利息每天都在悄悄累积（计息），但到约定日子才真正打到你账上（结息）。", pro: "计息是按积数或余额逐日计算应付利息的过程；结息是将累计利息正式入账的动作，活期多按季结息，定期到期结清。", example: "场景：活期存款每季度末月 20 日结息、21 日入账，你 3 月 21 日在账单里看到的那笔利息是整个季度的累计。易混：计息（算）vs 结息（付）——中间隔着的这段时间，利息是银行账上的「应付」，还不是你的余额。" },
  { id: "t-idempotent", term: "幂等", en: "Idempotency", plain: "同一个请求重复发十次，结果和发一次完全一样——绝不重复扣钱。", pro: "分布式系统中以全局流水号去重、保证请求重复执行不产生额外副作用的性质，是支付类接口设计的基本要求。", example: "场景：转账时网络超时你点了第二次，系统按流水号认出是同一笔，只扣一次款。易混：幂等解决「重复执行」，冲正解决「执行错了要撤销」，一个防重、一个纠错。" },
  { id: "t-sharding", term: "分库分表", en: "Sharding", plain: "一张大表装不下了，按客户号把数据拆到很多个库里存，各管一摊。", pro: "将单一数据库按分片键水平拆分为多个物理库表以突破单机容量与性能上限的技术，需配合分布式事务与全局唯一 ID 方案。", example: "场景：按客户号尾号分 64 片，你的账户数据固定在其中一片，本人账户互转不出片、跨片才走分布式事务。易混：分库分表是水平拆分（拆行），分区是单库内拆段，读写分离是拆负载——三者解决的问题不同。" },
  { id: "t-rpo", term: "RPO", en: "Recovery Point Objective", plain: "灾难发生时，最多能容忍丢掉多长时间的数据。核心系统通常要求约等于零。", pro: "容灾指标，指故障后数据恢复到的时间点与故障时点的最大允许差距，由数据复制方式（同步/异步）决定。", example: "场景：异地灾备异步复制延迟 3 分钟，灾难时最多丢 3 分钟的交易——RPO=3 分钟。易混：RPO 管「丢多少数据」，RTO 管「停多久业务」，一笔写一笔：RPO 看数据、RTO 看时间。" },
  { id: "t-rto", term: "RTO", en: "Recovery Time Objective", plain: "灾难发生后，业务最多多久必须重新跑起来。", pro: "容灾指标，指从故障发生到系统恢复对外服务的最大允许时长，双活架构可将其压缩到分钟级。", example: "场景：同城双活切换演练 4 分钟恢复服务，RTO 达标；冷备恢复要 4 小时，RTO 差一个量级。易混：RTO 的起点是「故障发生」不是「决定切换」，决策犹豫的两小时也算在 RTO 里——所以预案要预授权。" },
  { id: "t-2d3c", term: "两地三中心", en: "Two Sites, Three Centers", plain: "同城建两个机房互相备份，再在外地留一个灾备中心——一座城市出事，业务还能活。", pro: "同城双中心（双活/热备）+ 异地灾备中心的容灾布局，兼顾机房级故障的低 RPO/RTO 与城市级灾难的生存能力。", example: "场景：同城 A 中心火灾，双活的 B 中心分钟级接管；若整座城市断电，异地中心以小时级 RTO 恢复。易混：双活是「两个中心同时干活」，主备是「一个干活一个待命」，两地三中心里同城多为双活、异地多为灾备待命。" },
  { id: "t-routing", term: "Routing Number（ABA 号）", en: "ABA Routing Transit Number", plain: "美国银行的「联行号」：9 位数字，支票和转账靠它找到收款银行。", pro: "由美国银行家协会分配的金融机构标识码，用于 ACH、Fedwire 与支票清算的路由，是美国支付报文的基础字段。", example: "场景：美国人填直接存款表时要写 routing number + account number 两组数字，写错一位钱就去了别家银行。易混：中国客户不需要知道联行号（系统内部路由），美国客户必须自己填对——这是两国支付体验差异的源头之一。" },
  { id: "t-ach", term: "ACH", en: "Automated Clearing House", plain: "美国的「小额批量支付系统」：工资、账单靠它批量跑，便宜但通常隔日到账。", pro: "按 Nacha 规则运行的美国批量电子支付网络，处理借记与贷记批量交易，以轧差净额结算，时效以隔日为主、同日 ACH 逐步普及。", example: "场景：美国雇主周五发工资，ACH 隔日处理，员工周一才见钱——所以 Zelle 与 FedNow 才有存在的必要。易混：ACH ≈ 中国的小额批量系统（BEPS）的角色，但 ACH 是私营规则 + 双运营商，中国 BEPS 由央行运营。" },
  { id: "t-fdic", term: "FDIC 存款保险", en: "FDIC Deposit Insurance", plain: "美国版存款保险：银行倒了，储户每家银行 25 万美元以内的存款由它兜底。", pro: "美国联邦存款保险公司提供的存款保障制度，同一存款人在同一投保银行的同一所有权类别账户合计保障上限为 25 万美元（公开制度）。", example: "场景：2023 年硅谷银行倒闭时，FDIC 接管并保障储户存款，是存款保险最著名的实战案例（公开报道）。易混：FDIC 保的是存款不保投资（股票、基金、加密资产都不保），与中国的存款保险（50 万元人民币）是同构制度、不同参数。" },
  { id: "t-hvps", term: "大额支付系统（HVPS）", en: "High Value Payment System", plain: "央行开的「大额实时高速公路」：金额大、十万火急的跨行汇款走这里，逐笔即时到账。", pro: "人民银行运营的大额实时支付系统，对跨行大额债权债务逐笔全额实时结算，资金通过各行在央行的清算账户划拨。", example: "场景：企业下午付 2,000 万货款走 HVPS，供应商分钟级确认收款。易混：HVPS 逐笔全额结算、不轧差，与 BEPS 的批量轧差正相反——贵在最终性，贱在时效换成本。" },
  { id: "t-unitization", term: "单元化", en: "Cell-based Architecture", plain: "把客户按号段切成一个个独立单元，每个单元自己就能办全套业务，一个单元出事不连累其他。", pro: "按客户维度将系统与数据切分为可独立部署、独立容灾的单元（Cell），是国内大行分布式核心实现双活与弹性扩展的典型架构手法。", example: "场景：某单元所在机房故障，只影响该号段客户，其他单元照常——故障半径从「全行」缩到「一个单元」。易混：单元化是部署与容灾维度，分库分表是数据存储维度；单元内部仍然要分库分表，两者是包含关系不是替代关系。" },
  { id: "t-xinchuang", term: "信创", en: "Xinchuang (IT Application Innovation)", plain: "用国产芯片、操作系统、数据库、中间件，把银行 IT 的底子从国外产品换成自主可控的一套。", pro: "信息技术应用创新的简称，指以国产基础软硬件替代国外主导产品、构建自主可控 IT 底座的产业与工程实践，金融业是其重点推进领域之一。", example: "场景：某行把柜面系统从 x86 + Oracle 迁到鲲鹏 + 麒麟 + 达梦，SQL 改写与影子对账跑了三个月才切流。易混：信创 ≠ 买国产服务器，整栈等价适配（软件、工具链、运维经验）才是主体工程，硬件只是最容易的一层。" },
  { id: "t-deioe", term: "去 IOE", en: "De-IOE", plain: "把 IBM 的机器、Oracle 的数据库、EMC 的存储这套又贵又扩不动的组合，从系统里换出去。", pro: "源自 2013 年前后阿里巴巴的技术改造，指以分布式集群与自研/国产数据库替代 IBM 小型机、Oracle 数据库与 EMC 存储的架构转型；银行版本通常与分布式核心及信创改造合并推进。", example: "场景：银行把核心数据库从 Oracle 换成分布式国产库，同时完成分库分表——去 IOE 与分布式改造一次停机窗口办完。易混：去 IOE 是架构动作（换掉集中式贵栈），信创是供应链动作（换成国产栈），交集很大但出发点不同：一个为成本与扩展，一个为自主可控。" },
  { id: "t-dual-run", term: "双轨运行", en: "Dual Running / Parallel Run", plain: "新系统和老系统同时跑同一批业务，每天对账，分毫不差了才敢把老系统关掉。", pro: "系统切换期的并行验证方式：新旧系统同时处理真实或影子交易并逐日核对结果，是银行核心与信创替代工程控制切换风险的标准手段，通过后才进入灰度切流。", example: "场景：新核心上线后与老核心双跑三个月，每日逐户对余额与利息，连续无差错才启动分批切流。易混：双轨是「两套系统同时记账比对」，灰度是「流量逐步从老到新」，双轨验证等价性、灰度控制切换风险，顺序是先双轨后灰度。" },
  { id: "t-full-stack-compat", term: "全栈适配", en: "Full-stack Compatibility Adaptation", plain: "从芯片到操作系统到数据库到中间件，整摞都换成国产的，还得保证上面的应用跑起来结果不变。", pro: "对芯片、操作系统、数据库、中间件与应用软件进行整栈国产化替换与兼容性改造，包括代码重编译、SQL 方言改写、性能调优与工具链重建，目标是功能等价与账务结果一致。", example: "场景：一套柜面系统完成全栈适配的标志是：功能清单全过、影子账逐笔一致、日终批量在窗口内跑完——三条全过才算适配。易混：全栈适配强调「整栈 + 等价」，单换一层（只换数据库）叫单点替代，风险与工作量不在一个量级。" },
  { id: "t-ecny", term: "数字人民币（e-CNY）", en: "e-CNY / Digital RMB", plain: "央行直接发行的数字版人民币：和纸钞一样是法定货币、一样是央行的欠条，只是换成了数字形态，装在数字钱包里花。", pro: "中国人民银行发行的数字形式法定货币，定位于 M0（流通中现金），不计付利息、具有法偿性，由运营机构以双层运营模式向公众提供兑换与流通服务，目前处于试点推广阶段（公开口径）。", example: "场景：你从银行卡兑出 500 元到钱包，这 500 元就从「银行存款」变成了「数字现金」：不计息、不归存款保险管（它本身就是央行信用）。易混：数字人民币 vs 电子支付——支付宝、微信支付是「搬运存款的工具」，要经网联清算；数字人民币本身就是被搬运的「钱」，支付即结算，这是两者最本质的区别。" },
  { id: "t-two-tier", term: "双层运营", en: "Two-tier Operation", plain: "央行只管发行和定规则，不直接面对老百姓；银行等运营机构负责把钱包递到你手里、替你管账和服务。", pro: "央行数字货币的发行流通架构：第一层为中央银行（发行、规则、总量与登记），第二层为运营机构（钱包开立、兑换、流通服务与客户尽调），公众只与第二层发生关系，避免央行直接负债于公众、保护商业银行存款基础。", example: "场景：你的钱包丢了钱要找开钱包的那家银行走差错流程，而不是找央行——责任分层与存款业务一致。易混：双层运营 vs 双轨运行——前者是数字人民币的发行架构（央行→机构→公众），后者是系统切换期的新旧并行验证，读音相近、毫不相干。" },
  { id: "t-wallet-tier", term: "钱包分级", en: "e-CNY Wallet Tiers", plain: "数字钱包按实名程度分四档：给的信息越少、核验越松，能装的钱和能花的额度就越小。", pro: "按客户尽调强度将数字人民币钱包分为四类并匹配差异化限额的制度（试点公开口径）：一类柜面全量核验不限额；二类余额上限 50 万元、单笔 5 万元、日累计 10 万元；三类余额上限 5 万元、单笔 5,000 元、日累计 1 万元；四类仅手机号，余额上限 1 万元、年累计 5 万元量级；具体以运营机构现行规则为准。", example: "场景：游客只用手机号开了四类钱包，扫码吃饭够用，但想付 3,000 元的酒店押金就会超单笔限额——要升级二类钱包（绑卡实名）才行。易混：钱包分级 vs 银行账户一二三类户——逻辑同源（核验强度换额度），但分属两套体系：前者管数字人民币钱包，后者管存款账户，不能混着记。" },
  { id: "t-controlled-anonymity", term: "可控匿名", en: "Managed / Controllable Anonymity", plain: "小钱花得匿名、护隐私；大钱和可疑交易依法能查到人——在隐私和反洗钱之间刻意留的平衡点。", pro: "数字人民币的隐私保护原则，即「小额匿名、大额依法可溯」：小额交易以钱包标识处理、运营机构间不共享非必要身份信息；达到阈值或命中风险规则的交易，按法定程序关联实名信息并接受反洗钱监测。", example: "场景：你用钱包买 30 元早餐，商户只看到一笔到账、看不到你的姓名卡号；若同一钱包短期内出现大额高频异动，运营机构可依法调取实名信息甄别。易混：可控匿名 ≠ 完全匿名（现金才是完全匿名，数字人民币做不到也不追求）≠ 全面实名监控（每笔小额都实名留痕是账户支付的常态，数字人民币刻意区别于此）。" },
  { id: "t-east", term: "EAST", en: "Examination and Analysis System of Technology", plain: "监管的「明细取数口」：银行把每一笔贷款、每一笔存款的逐笔数据报给它，监管想查谁随时能调出来自己算。", pro: "国家金融监督管理总局的监管检查分析系统，采集银行业金融机构逐笔级业务与财务明细数据，支撑非现场监测与现场检查取数，与报汇总指标的 1104 形成明细—汇总勾稽关系。", example: "场景：监管用 EAST 明细自己汇总出某行不良余额，与该行 1104 报的数对不上，当场就能定位到哪类贷款的口径出了问题。易混：EAST 报明细（逐笔）、1104 报汇总（指标），一个是原料、一个是成品，成品必须能由原料加工出来。" },
  { id: "t-1104", term: "1104 报表", en: "CBIRC 1104 Regulatory Returns", plain: "银行每月季给监管交的「体检表」：资本、资产质量、流动性、盈利全在里面，监管盯盘主要盯它。", pro: "原银监会 2004 年启动的非现场监管报表体系（工程代号 1104），由金融机构按统一制度填报经营与风险汇总指标，是监管评级与日常监测的基础数据源，现由国家金融监督管理总局主管。", example: "场景：每月报送季，报送岗为表间校验里一个对不平的不良余额熬通宵——同一个指标在多张表里出现必须同数。易混：1104 是报表体系的名字不是一张表，具体表格以 G 开头编号（如 G01 资产负债表、G04 贷款质量表等，公开制度口径）。" },
  { id: "t-cips", term: "CIPS", en: "Cross-border Interbank Payment System", plain: "人民币跨境的「清算高速」：境内外银行的人民币付款在里面直接结算，不用先换成美元绕地球。", pro: "人民币跨境支付系统，由跨境银行间支付清算公司运营，为境内外参与者提供跨境人民币报文与资金清算服务，参与者分直接参与者（开户直连）与间接参与者（经直接参与者接入）两层。", example: "场景：深圳企业付人民币货款到泰国，资金经 CIPS 当日结到泰国银行的 CIPS 账户，供应商收到全额人民币。易混：CIPS vs SWIFT——SWIFT 只传报文不碰钱，CIPS 报文与清算一体；CIPS vs CBETS——CIPS 流的是存款人民币，CBETS 流的是数字人民币。" },
  { id: "t-acceptance", term: "承兑", en: "Acceptance", plain: "在票据上签字认账：银行一旦承兑，就等于承诺这张票到期由我无条件付款，票的身价立刻不一样。", pro: "付款人在汇票到期前确认到期付款的票据行为；经银行承兑的汇票（银行承兑汇票）以承兑行信用为付款保证，到期承兑行须无条件付款，出票人资金不足时由承兑行垫付。", example: "场景：买方企业开的票经银行承兑后，卖方拿着它去贴现，利率按银行信用定价——若是企业自己承兑的商票，利率高得多还未必有人收。易混：承兑（认票）vs 贴现（卖票换钱）——承兑发生在出票端、创造信用，贴现发生在持票端、变现信用。" },
  { id: "t-discount", term: "贴现", en: "Discounting", plain: "没到期的票先卖给银行换现金，银行按剩余天数扣掉利息——本质是拿未来的钱打折买现在。", pro: "持票人将未到期票据背书转让给银行、银行扣除贴现利息后支付票款的融资行为，属授信业务，须审核贸易背景并占用授信额度；贴现利率市场化形成，随资金面与票据供需波动。", example: "场景：100 万元、还剩 4 个月的银票，按年化 1.8% 示例利率贴现扣息 6,000 元，企业实收 99.4 万元。易混：贴现 vs 质押——贴现是卖断（票归银行），质押是抵押（票仍归企业、到期托收还贷）；贴现 vs 转贴现——转贴现是银行之间买卖已贴现票据。" },
  { id: "t-ftp", term: "FTP（内部资金转移定价）", en: "Funds Transfer Pricing", plain: "银行内部的「资金批发价」：存款部门把钱按这个价卖给资金池，贷款部门按这个价买钱，利差先在内部切一刀。", pro: "银行内部资金的价格机制，由司库/ALCO 按期限与币种发布价格曲线，用于计量各条线、各机构、各产品的资金成本与资金收入，是管理会计切分利润、管理利率风险的基础工具。", example: "场景：一笔 5 年期房贷利率 3.6%、FTP 价 2.3%，贷款条线只赚 1.3% 的业务利差，其余利差归资金池与存款条线。易混：FTP 是内部价（客户看不见），LPR 是对外贷款定价锚——客户利率在 FTP 之上加风险与资本成本形成，与 LPR 挂钩报价是另一层定价机制。" },
  { id: "t-lcr", term: "流动性覆盖率（LCR）", en: "Liquidity Coverage Ratio", plain: "压力测试式的体检：假设未来 30 天大家来挤兑，银行手里的好资产够不够付——必须 ≥100%。", pro: "巴塞尔 III 流动性监管指标：合格优质流动性资产 ÷ 未来 30 天压力情景下现金净流出量，监管要求不低于 100%（公开监管标准口径），衡量短期流动性韧性；与管长期结构的净稳定资金比例 NSFR 配对使用。", example: "场景：2023 年硅谷银行事件后，各国监管都在重审 LCR 的流出率假设——数字时代的存款跑得比假设快得多。易混：LCR 管 30 天短期、NSFR 管一年长期；LCR 是「存量好资产 vs 流量净流出」，不是简单的现金够不够。" },
  { id: "t-mgmt-acct", term: "管理会计", en: "Management Accounting", plain: "给银行自己看的账：把利润算到每个分行、每个产品、每个客户头上，看清到底谁在赚钱、谁在赔。", pro: "以内部经营决策为目的的会计体系，含内部资金转移定价、成本分摊与多维盈利分析，口径独立于对外披露的法定会计，但数据同源、规则成文，两者不得互相冒充。", example: "场景：某分行账面利润 3.5 亿元，扣完 FTP 切分与总行成本分摊后管理利润 2.8 亿元，奖金按后者算——分行行长从此认真对待存款结构。易混：管理会计 vs 财务会计——后者对外、法定、求真，前者对内、管理、求有用；数字不同是设计，不是造假。" },
  { id: "t-data-gov", term: "数据治理", en: "Data Governance", plain: "给全行数据立规矩：每个数字谁定义、谁负责、错了找谁——让同一个指标全行只有一个版本。", pro: "对数据标准、质量、主数据、元数据与血缘进行权责化管理的体系，核心是数据主人机制与口径裁定权归属业务部门，是监管报送、风险计量与经营分析可信度的共同地基。", example: "场景：信贷部与风险部为不良余额吵了一上午，治理委员会裁定统一口径并在监管集市固化，从此会上先问「哪个口径」再谈数字。易混：数据治理 vs 数据清洗——清洗是把脏数据洗一遍，治理是让数据不再变脏（标准、权责、检核、考核），一个是体力活、一个是制度活。" },
  { id: "t-mdm", term: "主数据", en: "Master Data", plain: "全行共用的「名词表」：客户、机构、产品这些核心对象，每样只有一个官方版本，所有系统都认它。", pro: "跨系统共享的核心业务实体数据（客户、机构、产品、员工等），由主数据管理（MDM）维护唯一编码与黄金记录，变更经审批后向全部订阅系统广播同步。", example: "场景：一家支行撤并，机构代码在 MDM 里变更并广播，漏播的一个系统当晚报表就把该支行的数算进了别人家。易混：主数据 vs 交易数据——主数据是「名词」（谁、哪个机构、什么产品），交易数据是「动词」（谁在何时转了多少钱），名词错一位，动词全错位。" },
  { id: "t-custody", term: "资产托管", en: "Asset Custody", plain: "把别人的钱和券放在我这儿保管、交收、算账，还替投资者盯着管理人别乱来——保管箱加监工。", pro: "托管人接受委托，为基金、理财、年金等产品提供资产保管、清算交收、估值复核与投资监督的受托服务；托管资产独立于托管人与管理人自有财产，不属于任何一方的清算财产。", example: "场景：公募基金买国债，券登记在基金的托管账户、钱从托管账户划付，管理人全程碰不到资产，净值还要托管行复核过才公布。易混：托管 vs 保管——保管只管存放，托管还管交收、估值与监督；托管 vs TA——托管管资产侧（钱与券），TA 管份额侧（谁持有多少份）。" },
  { id: "t-csd", term: "中央存管（登记结算）", en: "Central Securities Depository (CSD)", plain: "全国证券的「不动产登记中心」：券登记在谁名下，法律上就归谁，所有买卖最终都要到它这儿过户。", pro: "集中登记、存管与结算证券的金融市场基础设施；中国按市场分设中债登（银行间债券）、中证登（交易所证券）、上海清算所（衍生品与部分信用产品），美国为 DTCC 体系。证券所有权以其登记为最终依据。", example: "场景：基金买的国债过户登记在中债登的托管账户名下，哪天对持仓有争议，登记记录就是终局证据。易混：中央存管 vs 托管银行——存管是市场级的登记权威（一国少数几家），托管行是面向产品的受托服务商（多家竞争），前者是登记处、后者是管家。" },
  { id: "t-lc", term: "信用证", en: "Letter of Credit (L/C)", plain: "银行给买卖双方的「信任替代品」：卖家按约发货交单，银行保证付钱；买家凭单提货，钱货两讫不靠交情。", pro: "开证行应申请人要求向受益人开立的、在单证相符时承担付款责任的书面承诺，遵循国际商会 UCP600 惯例；具有独立性（独立于买卖合同）与单据性（银行处理单据不处理货物）两大原则。", example: "场景：进口商开 90 天远期信用证买设备，出口商发货交单、开证行审单相符即承兑，进口商先提货销售、到期再付钱赎单。易混：信用证 vs 保函——信用证是主动付款安排（单证相符就付），保函是违约兜底（对方违约且索赔相符才付），一个管「正常履约的支付」、一个管「出事时的赔付」。" },
  { id: "t-guarantee", term: "保函", en: "Bank Guarantee", plain: "银行替企业向对方出具的「他办不到，我来赔」的书面承诺：投标、履约、预付款，工程和贸易里到处都是。", pro: "银行应申请人要求向受益人出具的书面付款保证，独立保函下受益人凭相符索赔单据即可索款（见索即付），保函开出即形成银行表外信用敞口并占用申请人授信额度。", example: "场景：建筑公司投标要交投标保函，中标后换履约保函，银行全程只出一张纸，但这张纸占的是真授信、担的是真赔付。易混：保函 vs 保证——保函是银行独立的第一性付款责任，民法上的保证多为从属性（主债务人不还才轮到保证人），银行保函的「独立性」正是它值钱的地方。" },
  { id: "t-scf", term: "供应链金融", en: "Supply Chain Finance", plain: "借核心企业的信用给它的小供应商输血：大企业确认欠款，小供应商拿着这张确认就能向银行借到便宜钱。", pro: "围绕核心企业信用、基于真实贸易应收应付关系的融资安排，含应收账款质押与保理、订单融资、电子债权凭证多级流转等形态，风控核心是核心企业确权与应收账款登记防重复融资。", example: "场景：车企确认欠零部件商 500 万元、账期 6 个月，零部件商凭确权的电子债权凭证向银行融资，利率认的是车企的信用而非自己的。易混：供应链金融 vs 普通小企业贷款——有确权与登记的是前者（信用主体是核心企业），没有确权只是换名字的后者，两者的风险定价完全不同。" },
];
